/* @autogenerated */
import { Component, inject } from '@angular/core';
import { TenantTermsOfUse } from 'app/features/identity/tenant-terms-of-use/model/tenant-terms-of-use.model';
import { TenantTermsOfUseRepository } from 'app/features/identity/tenant-terms-of-use/repository/tenant-terms-of-use-repository.service';
import { ConfirmAction } from 'app/shared/toolkit/action/confirm-action';

@Component({ selector: 'tenant-terms-of-use-view-disable-action', standalone: false, template: '' })
export class TenantTermsOfUseViewDisableActionComponent extends ConfirmAction<TenantTermsOfUse> {
  readonly name = 'disable';
  protected readonly scope = 'identity/tenant-terms-of-use';
  protected readonly repository = inject(TenantTermsOfUseRepository);

  protected override appliesTo(items: TenantTermsOfUse[]) {
    return items.every((item) => !!item.enabled);
  }

  protected execute([item]: TenantTermsOfUse[]) {
    return this.repository.disable(item.uid);
  }
}
